    private static void applyEnemyWeights() throws GameActionException {
        for (int i = 0; i < RobotTracker.numEnemies && i < 5; i++) {
            RobotInfo info = RobotTracker.sortedEnemies[i];
            if (info.getType() != UnitType.BABY_RAT) continue;
            applyEnemyWeight(info);
        }
    }

    private static double getWeight(int dx, int dy) {
        switch (dx) {
            case -2 -> {
                switch (dy) {
                    case -2 -> {
                        return w_m2_m2;
                    }
                    case -1 -> {
                        return w_m2_m1;
                    }
                    case 0 -> {
                        return w_m2_0;
                    }
                    case 1 -> {
                        return w_m2_1;
                    }
                    case 2 -> {
                        return w_m2_2;
                    }
                    default -> { return -1000; }
                }
            }
            case -1 -> {
                switch (dy) {
                    case -2 -> {
                        return w_m1_m2;
                    }
                    case -1 -> {
                        return w_m1_m1;
                    }
                    case 0 -> {
                        return w_m1_0;
                    }
                    case 1 -> {
                        return w_m1_1;
                    }
                    case 2 -> {
                        return w_m1_2;
                    }
                    default -> { return -1000; }
                }
            }
            case 0 -> {
                switch (dy) {
                    case -2 -> {
                        return w_0_m2;
                    }
                    case -1 -> {
                        return w_0_m1;
                    }
                    case 0 -> {
                        return w_0_0;
                    }
                    case 1 -> {
                        return w_0_1;
                    }
                    case 2 -> {
                        return w_0_2;
                    }
                    default -> { return -1000; }
                }
            }
            case 1 -> {
                switch (dy) {
                    case -2 -> {
                        return w_1_m2;
                    }
                    case -1 -> {
                        return w_1_m1;
                    }
                    case 0 -> {
                        return w_1_0;
                    }
                    case 1 -> {
                        return w_1_1;
                    }
                    case 2 -> {
                        return w_1_2;
                    }
                    default -> { return -1000; }
                }
            }
            case 2 -> {
                switch (dy) {
                    case -2 -> {
                        return w_2_m2;
                    }
                    case -1 -> {
                        return w_2_m1;
                    }
                    case 0 -> {
                        return w_2_0;
                    }
                    case 1 -> {
                        return w_2_1;
                    }
                    case 2 -> {
                        return w_2_2;
                    }
                    default -> { return -1000; }
                }
            }
            default -> { return -1000; }
        }
    }

