    private static void moveN() throws GameActionException {
        if (!CombatCommon.canMoveN) return;
        curMoveLoc = myLoc.add(Direction.NORTH);
        faceNN();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceNEN();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceNWN();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
    }


