    private static void moveNE() throws GameActionException {
        if (!CombatCommon.canMoveNE) return;
        curMoveLoc = myLoc.add(Direction.NORTHEAST);
        faceNENE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceNNE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceENE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
    }


