    private static void moveE() throws GameActionException {
        if (!CombatCommon.canMoveE) return;
        curMoveLoc = myLoc.add(Direction.EAST);
        faceEE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceNEE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceSEE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
    }


