    private static void moveSE() throws GameActionException {
        if (!CombatCommon.canMoveSE) return;
        curMoveLoc = myLoc.add(Direction.SOUTHEAST);
        faceSESE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceSSE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceESE();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
    }


