    private static void moveS() throws GameActionException {
        if (!CombatCommon.canMoveS) return;
        curMoveLoc = myLoc.add(Direction.SOUTH);
        faceSS();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceSES();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceSWS();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
    }


