    private static void moveSW() throws GameActionException {
        if (!CombatCommon.canMoveSW) return;
        curMoveLoc = myLoc.add(Direction.SOUTHWEST);
        faceSWSW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceSSW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceWSW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
    }


