    private static void moveW() throws GameActionException {
        if (!CombatCommon.canMoveW) return;
        curMoveLoc = myLoc.add(Direction.WEST);
        faceWW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceNWW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceSWW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
    }


