    private static void moveNW() throws GameActionException {
        if (!CombatCommon.canMoveNW) return;
        curMoveLoc = myLoc.add(Direction.NORTHWEST);
        faceNWNW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceNNW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
        faceWNW();
        if (Clock.getBytecodeNum() - bytecodeStart > bytecodeBudget) return;
    }


